/// The crate root's own documentation, as the MARKDOWN a `#![doc = include_str!(…)]` wants.
///
/// `//!` is a doc comment in Rust and noise in markdown, so the marker is stripped and the prose is
/// kept verbatim — including its rustdoc intra-doc links, which resolve identically from an included
/// markdown file because the attribute sits in the real crate root rather than in an `include!`d one.
/// That distinction is the whole reason this migration is possible; see [`root_is_bare`].
pub fn crate_doc_markdown(lib_src: &str) -> String {
    let mut out: Vec<&str> = Vec::new();
    for line in lib_src.lines() {
        let t = line.trim_start();
        let Some(rest) = t.strip_prefix("//!") else { continue };
        out.push(rest.strip_prefix(' ').unwrap_or(rest));
    }
    let mut doc = out.join("\n");
    if !doc.is_empty() && !doc.ends_with('\n') {
        doc.push('\n');
    }
    doc
}
